   Float_t         genP_;
   Float_t         genEta_;
   Float_t         genPhi_;
   Float_t         trkP_;
   Float_t         trkEta_;
   Float_t         trkPhi_;
   Float_t         hfem_;
   Float_t         hfhad_;
